package dev.soundceiling.app;
import android.content.Context;import android.content.SharedPreferences;
final class Prefs{private static final String FILE="sound_ceiling";static final String TARGET_RMS="target_rms",PEAK_CEILING="peak_ceiling",TARGET_SPL="target_spl",SPL_CEILING="spl_ceiling",MAX_VOLUME_PERCENT="max_volume_percent",NORMALIZE="normalize",SPL_MODE="spl_mode",COMPRESSION_PERCENT="compression_percent",LAST_MEASURED_SPL="last_measured_spl",UI_MODE="ui_mode",SPEED_PRESET="speed_preset",ALLOW_AUTO_MUTE="allow_auto_mute",LAST_LOG_URI="last_log_uri";static SharedPreferences get(Context c){return c.getSharedPreferences(FILE,Context.MODE_PRIVATE);}static float targetRms(Context c){return get(c).getFloat(TARGET_RMS,-18f);}static float peakCeiling(Context c){return get(c).getFloat(PEAK_CEILING,-3f);}static float targetSpl(Context c){return get(c).getFloat(TARGET_SPL,70f);}static float splCeiling(Context c){return get(c).getFloat(SPL_CEILING,80f);}static int maxVolumePercent(Context c){return get(c).getInt(MAX_VOLUME_PERCENT,70);}static boolean normalize(Context c){return get(c).getBoolean(NORMALIZE,true);}static boolean splMode(Context c){return get(c).getBoolean(SPL_MODE,false);}static int compressionPercent(Context c){return get(c).getInt(COMPRESSION_PERCENT,100);}static int lastMeasuredSpl(Context c){return get(c).getInt(LAST_MEASURED_SPL,70);}static String uiMode(Context c){return get(c).getString(UI_MODE,"simple");}static SpeedPreset speedPreset(Context c){return SpeedPreset.fromKey(get(c).getString(SPEED_PRESET,"balanced"));}static boolean allowAutoMute(Context c){return get(c).getBoolean(ALLOW_AUTO_MUTE,false);}private Prefs(){}}
